1	/**
2	 * Insert one Improvement proposal into the board (app/admin/improvements).
3	 *
4	 * Meant to be called by the nightly scan, one invocation per finding:
5	 *
6	 *   npx tsx scripts/write-improvement.ts \
7	 *     --category bug --severity high \
8	 *     --title "Race in provisioning worker" \
9	 *     --summary "Two jobs can grab the same IP under load." \
10	 *     [--detail "..."] [--batchId 2026-07-24] [--source nightly-scan] \
11	 *     [--effort M] [--filesHint "lib/provisioner.ts"]
12	 *
13	 * The runner is CJS, so there is NO top-level await — everything runs inside
14	 * main().
15	 */
16	
17	import { db } from "../lib/db";
18	
19	/** Parse --key value / --key=value flags into a map. */
20	function parseArgs(argv: string[]): Record<string, string> {
21	  const out: Record<string, string> = {};
22	  for (let i = 0; i < argv.length; i++) {
23	    const a = argv[i];
24	    if (!a.startsWith("--")) continue;
25	    const key = a.slice(2);
26	    const eq = key.indexOf("=");
27	    if (eq >= 0) {
28	      out[key.slice(0, eq)] = key.slice(eq + 1);
29	    } else {
30	      const next = argv[i + 1];
31	      if (next && !next.startsWith("--")) {
32	        out[key] = next;
33	        i++;
34	      } else {
35	        out[key] = "true";
36	      }
37	    }
38	  }
39	  return out;
40	}
41	
42	const CATEGORIES = ["bug", "feature", "error", "enhancement", "security", "performance"];
43	const SEVERITIES = ["low", "medium", "high", "critical"];
44	const EFFORTS = ["S", "M", "L"];
45	
46	async function main() {
47	  const args = parseArgs(process.argv.slice(2));
48	
49	  const category = (args.category ?? "").toLowerCase().trim();
50	  const severity = (args.severity ?? "medium").toLowerCase().trim();
51	  const title = (args.title ?? "").trim();
52	  const summary = (args.summary ?? "").trim();
53	
54	  const missing: string[] = [];
55	  if (!category) missing.push("--category");
56	  if (!title) missing.push("--title");
57	  if (!summary) missing.push("--summary");
58	  if (missing.length) {
59	    console.error(`write-improvement: missing required flag(s): ${missing.join(", ")}`);
60	    process.exit(1);
61	  }
62	  if (!CATEGORIES.includes(category)) {
63	    console.error(`write-improvement: --category must be one of ${CATEGORIES.join(" | ")}`);
64	    process.exit(1);
65	  }
66	  if (!SEVERITIES.includes(severity)) {
67	    console.error(`write-improvement: --severity must be one of ${SEVERITIES.join(" | ")}`);
68	    process.exit(1);
69	  }
70	
71	  const effort = args.effort ? args.effort.toUpperCase().trim() : null;
72	  if (effort && !EFFORTS.includes(effort)) {
73	    console.error(`write-improvement: --effort must be one of ${EFFORTS.join(" | ")}`);
74	    process.exit(1);
75	  }
76	
77	  const row = await db.improvement.create({
78	    data: {
79	      category,
80	      severity,
81	      title,
82	      summary,
83	      detail: args.detail ?? null,
84	      batchId: args.batchId ?? null,
85	      source: args.source ?? "nightly-scan",
86	      effort,
87	      filesHint: args.filesHint ?? null,
88	      status: "PROPOSED",
89	    },
90	  });
91	
92	  console.log(`Improvement created: ${row.id} [${row.category}/${row.severity}] ${row.title}`);
93	  await db.$disconnect();
94	}
95	
96	main().catch(async (e) => {
97	  console.error(e);
98	  try {
99	    await db.$disconnect();
100	  } catch {
101	    /* ignore */
102	  }
103	  process.exit(1);
104	});
105

1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { requireAdmin } from "@/lib/auth";
5	import { db } from "@/lib/db";
6	
7	/**
8	 * Owner-facing approve/decline actions for the Improvements board
9	 * (app/admin/improvements). Every action is ADMIN-guarded via requireAdmin(),
10	 * mirroring the other admin action modules.
11	 */
12	
13	export const IMPROVEMENT_STATUSES = [
14	  "PROPOSED",
15	  "APPROVED",
16	  "DECLINED",
17	  "IN_PROGRESS",
18	  "DONE",
19	] as const;
20	
21	export type ImprovementStatus = (typeof IMPROVEMENT_STATUSES)[number];
22	
23	function assertStatus(status: string): asserts status is ImprovementStatus {
24	  if (!(IMPROVEMENT_STATUSES as readonly string[]).includes(status)) {
25	    throw new Error(`Invalid improvement status: ${status}`);
26	  }
27	}
28	
29	async function audit(userId: string | null, action: string, detail?: string) {
30	  try {
31	    await db.auditLog.create({ data: { userId, action, detail } });
32	  } catch {
33	    /* auditing is best-effort — never block the status change on it */
34	  }
35	}
36	
37	/** Set a single improvement's status. */
38	export async function setImprovementStatus(id: string, status: string): Promise<void> {
39	  const admin = await requireAdmin();
40	  assertStatus(status);
41	  await db.improvement.update({ where: { id }, data: { status } });
42	  await audit(admin.id, "improvement.status", `${id} → ${status}`);
43	  revalidatePath("/admin/improvements");
44	}
45	
46	/** Selector for a bulk status change: an explicit id list and/or a filter. */
47	export type BulkImprovementSelector = {
48	  /** Explicit row ids. */
49	  ids?: string[];
50	  /** Restrict to a category (e.g. "bug"). */
51	  category?: string;
52	  /** Only touch rows currently in this status (e.g. only PROPOSED). */
53	  onlyStatus?: string;
54	};
55	
56	/**
57	 * Bulk status change. Accepts either an explicit id list, a filter (category /
58	 * current status), or both. With no constraints at all it is a no-op guard —
59	 * we refuse an unbounded update so "Approve all" can never sweep the whole
60	 * table by accident.
61	 */
62	export async function bulkSetStatus(
63	  selector: BulkImprovementSelector,
64	  status: string
65	): Promise<{ count: number }> {
66	  const admin = await requireAdmin();
67	  assertStatus(status);
68	
69	  const where: {
70	    id?: { in: string[] };
71	    category?: string;
72	    status?: string;
73	  } = {};
74	  if (selector.ids && selector.ids.length > 0) where.id = { in: selector.ids };
75	  if (selector.category) where.category = selector.category;
76	  if (selector.onlyStatus) {
77	    assertStatus(selector.onlyStatus);
78	    where.status = selector.onlyStatus;
79	  }
80	
81	  // Refuse a truly unconstrained bulk update.
82	  if (Object.keys(where).length === 0) return { count: 0 };
83	
84	  const res = await db.improvement.updateMany({ where, data: { status } });
85	  await audit(
86	    admin.id,
87	    "improvement.bulkStatus",
88	    `${res.count} row(s) → ${status} (${JSON.stringify(selector)})`
89	  );
90	  revalidatePath("/admin/improvements");
91	  return { count: res.count };
92	}
93

