/**
 * Laptop-independent nightly scanner for Nxeon.
 *
 * Runs on the Proxmox host via a systemd timer (see deploy/nxeon-nightly-scan.*),
 * gathers real read-only signals about the running system, and writes deduped
 * proposals into the `Improvement` table so the admin Improvements board
 * (app/admin/improvements) keeps filling up even when the owner's laptop is off.
 *
 * Every signal collector is wrapped in try/catch so a single failure (e.g. no
 * journal access) never aborts the whole run. Dedup: any proposal whose title
 * already exists in an active improvement (PROPOSED | APPROVED | IN_PROGRESS) is
 * skipped, so we never repropose the same finding night after night.
 *
 * The runner is CJS, so there is NO top-level await — everything runs inside
 * main(), mirroring scripts/write-improvement.ts.
 */

import { execFileSync } from "node:child_process";
import { db } from "../lib/db";

/** A single finding, before dedup + persistence. */
type Proposal = {
  category: string; // bug | feature | error | enhancement | security | performance
  severity: string; // low | medium | high | critical
  title: string; // MUST be stable across runs so dedup works (no counts/dates)
  summary: string; // one concise sentence
  detail?: string | null;
  effort?: string | null; // S | M | L
  filesHint?: string | null;
};

const DAY_MS = 24 * 60 * 60 * 1000;
const now = new Date();
const since = new Date(now.getTime() - DAY_MS);

/** batchId = today's date (YYYY-MM-DD) in local time. */
function todayBatchId(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/** Map an occurrence count to a severity bucket. */
function severityForCount(n: number): string {
  if (n >= 50) return "critical";
  if (n >= 20) return "high";
  if (n >= 5) return "medium";
  return "low";
}

function truncate(s: string, max: number): string {
  const t = s.replace(/\s+/g, " ").trim();
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}

// ---------------------------------------------------------------------------
// Signal collectors — each returns Proposal[] and swallows its own errors.
// ---------------------------------------------------------------------------

/**
 * (a) Server errors: cluster recurring error lines from the two service
 * journals over the last 24h and propose the top few.
 */
function collectServerErrors(): Proposal[] {
  try {
    const raw = execFileSync(
      "journalctl",
      [
        "-u",
        "nxeon-web",
        "-u",
        "nxeon-worker",
        "--since",
        "24 hours ago",
        "-p",
        "err",
        "--no-pager",
      ],
      { encoding: "utf8", maxBuffer: 32 * 1024 * 1024, timeout: 30_000 }
    );

    const lines = raw
      .split("\n")
      .map((l) => l.trim())
      .filter((l) => l.length > 0 && !/^-- /.test(l)); // drop "-- No entries --" etc.

    // Strip the syslog prefix ("Mon DD HH:MM:SS host unit[pid]: ") to get the message.
    const extractMessage = (line: string): string => {
      const m = line.match(
        /^[A-Z][a-z]{2}\s+\d+\s+\d{2}:\d{2}:\d{2}\s+\S+\s+\S+?:\s+(.*)$/
      );
      return m ? m[1] : line;
    };

    // Normalize volatile tokens (numbers, hex, uuids) so similar lines cluster.
    const normalize = (msg: string): string =>
      msg
        .toLowerCase()
        .replace(/0x[0-9a-f]+/g, "0x#")
        .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g, "<uuid>")
        .replace(/\d+/g, "#")
        .replace(/\s+/g, " ")
        .trim();

    const clusters = new Map<string, { count: number; sample: string }>();
    for (const line of lines) {
      const msg = extractMessage(line);
      if (!msg) continue;
      const key = normalize(msg);
      if (!key) continue;
      const existing = clusters.get(key);
      if (existing) existing.count++;
      else clusters.set(key, { count: 1, sample: msg });
    }

    const ranked = [...clusters.entries()]
      .filter(([, v]) => v.count >= 2) // only genuinely recurring lines
      .sort((a, b) => b[1].count - a[1].count)
      .slice(0, 3);

    return ranked.map(([key, v]) => ({
      category: "error",
      severity: severityForCount(v.count),
      // Title uses the NORMALIZED signature -> stable across nights (no counts).
      title: `Recurring server error: ${truncate(key, 90)}`,
      summary: `A server log error recurred ${v.count} time(s) in the last 24h across nxeon-web/nxeon-worker.`,
      detail: `Sample line:\n${truncate(v.sample, 500)}\n\nOccurrences (last 24h): ${v.count}`,
      effort: "M",
      filesHint: "lib/, worker/, app/api/",
    }));
  } catch {
    return [];
  }
}

/** (b) Failed jobs in the last 24h, grouped by job type. */
async function collectFailedJobs(): Promise<Proposal[]> {
  try {
    const groups = await db.job.groupBy({
      by: ["type"],
      where: { status: "FAILED", updatedAt: { gte: since } },
      _count: { _all: true },
    });

    const out: Proposal[] = [];
    for (const g of groups) {
      const count = g._count._all;
      if (count <= 0) continue;
      const sample = await db.job.findFirst({
        where: { type: g.type, status: "FAILED", updatedAt: { gte: since } },
        orderBy: { updatedAt: "desc" },
        select: { id: true, error: true, attempts: true },
      });
      out.push({
        category: "bug",
        severity: severityForCount(count),
        title: `Failed ${g.type} jobs in the last 24h`,
        summary: `${count} ${g.type} job(s) failed in the last 24h — investigate the worker path.`,
        detail: sample
          ? `Latest failure: job ${sample.id} (attempts=${sample.attempts})\nError: ${truncate(
              sample.error ?? "(none recorded)",
              500
            )}`
          : null,
        effort: "M",
        filesHint: "worker/, lib/provisioner.ts",
      });
    }
    return out;
  } catch {
    return [];
  }
}

/** (c) Failed emails in the last 24h. */
async function collectFailedEmails(): Promise<Proposal[]> {
  try {
    const failed = await db.emailLog.findMany({
      where: { status: "FAILED", createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      select: { toEmail: true, subject: true, template: true, error: true },
    });
    if (failed.length === 0) return [];

    const sample = failed[0];
    return [
      {
        category: "bug",
        severity: severityForCount(failed.length),
        title: "Email delivery failures in the last 24h",
        summary: `${failed.length} outbound email(s) failed to send in the last 24h — check the mailer/SMTP path.`,
        detail: `Latest failure — template=${sample.template ?? "(none)"} subject="${truncate(
          sample.subject,
          80
        )}"\nError: ${truncate(sample.error ?? "(none recorded)", 400)}`,
        effort: "S",
        filesHint: "lib/mailer.ts",
      },
    ];
  } catch {
    return [];
  }
}

/** (d) Jobs stuck in RUNNING for more than ~30 minutes. */
async function collectStuckJobs(): Promise<Proposal[]> {
  try {
    const cutoff = new Date(now.getTime() - 30 * 60 * 1000);
    const stuck = await db.job.findMany({
      where: { status: "RUNNING", updatedAt: { lte: cutoff } },
      orderBy: { updatedAt: "asc" },
      select: { id: true, type: true, updatedAt: true },
    });
    if (stuck.length === 0) return [];

    const lines = stuck
      .slice(0, 10)
      .map(
        (j) =>
          `${j.type} ${j.id} — last update ${j.updatedAt.toISOString()} (${Math.round(
            (now.getTime() - j.updatedAt.getTime()) / 60000
          )}m ago)`
      )
      .join("\n");

    return [
      {
        category: "error",
        severity: stuck.length >= 3 ? "high" : "medium",
        title: "Jobs stuck in RUNNING for over 30 minutes",
        summary: `${stuck.length} job(s) have been RUNNING for over 30 minutes — likely a hung or crashed worker.`,
        detail: `Stuck jobs:\n${lines}`,
        effort: "M",
        filesHint: "worker/, lib/jobs.ts",
      },
    ];
  } catch {
    return [];
  }
}

/** (e) New customer feedback (status NEW) in the last 24h. */
async function collectNewFeedback(): Promise<Proposal[]> {
  try {
    const rows = await db.feedback.findMany({
      where: { status: "NEW", createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      select: { kind: true, title: true },
    });
    if (rows.length === 0) return [];

    const hasBug = rows.some((r) => (r.kind ?? "").toUpperCase() === "BUG");
    const listed = rows
      .slice(0, 10)
      .map((r) => `[${r.kind}] ${truncate(r.title, 80)}`)
      .join("\n");

    return [
      {
        category: hasBug ? "bug" : "feature",
        severity: hasBug ? "medium" : "low",
        title: "Review new customer feedback",
        summary: `${rows.length} new feedback item(s) arrived in the last 24h and need triage on the board.`,
        detail: `New feedback (status NEW):\n${listed}`,
        effort: "S",
        filesHint: "app/admin/feedback",
      },
    ];
  } catch {
    return [];
  }
}

/** (e2) Open support tickets flagged as bugs. */
async function collectBugTickets(): Promise<Proposal[]> {
  try {
    const tickets = await db.ticket.findMany({
      where: {
        status: { in: ["OPEN", "CUSTOMER_REPLY"] },
        OR: [
          { subject: { contains: "bug", mode: "insensitive" } },
          { subject: { contains: "error", mode: "insensitive" } },
          { subject: { contains: "broken", mode: "insensitive" } },
        ],
      },
      orderBy: { updatedAt: "desc" },
      select: { id: true, subject: true, priority: true },
    });
    if (tickets.length === 0) return [];

    const listed = tickets
      .slice(0, 10)
      .map((t) => `[${t.priority}] ${truncate(t.subject, 80)}`)
      .join("\n");

    return [
      {
        category: "bug",
        severity: tickets.some((t) => t.priority === "URGENT" || t.priority === "HIGH")
          ? "high"
          : "medium",
        title: "Review open bug-flagged support tickets",
        summary: `${tickets.length} open support ticket(s) look bug-related and may indicate a real defect.`,
        detail: `Bug-flagged tickets:\n${listed}`,
        effort: "M",
        filesHint: "app/admin/tickets",
      },
    ];
  } catch {
    return [];
  }
}

/** (f) Open abuse alerts. */
async function collectAbuseAlerts(): Promise<Proposal[]> {
  try {
    const count = await db.abuseAlert.count({ where: { status: "OPEN" } });
    if (count <= 0) return [];
    return [
      {
        category: "security",
        severity: count >= 5 ? "high" : "medium",
        title: "Open abuse alerts need review",
        summary: `${count} abuse alert(s) are still OPEN and need acknowledgement or action.`,
        detail: null,
        effort: "S",
        filesHint: "app/admin/abuse",
      },
    ];
  } catch {
    return [];
  }
}

// ---------------------------------------------------------------------------

async function main() {
  const batchId = todayBatchId(now);
  const proposals: Proposal[] = [];

  // Gather every signal; collectors never throw.
  proposals.push(...collectServerErrors());
  proposals.push(...(await collectFailedJobs()));
  proposals.push(...(await collectFailedEmails()));
  proposals.push(...(await collectStuckJobs()));
  proposals.push(...(await collectNewFeedback()));
  proposals.push(...(await collectBugTickets()));
  proposals.push(...(await collectAbuseAlerts()));

  // Dedup against active improvements (never repropose an open finding).
  let existingTitles = new Set<string>();
  try {
    const existing = await db.improvement.findMany({
      where: { status: { in: ["PROPOSED", "APPROVED", "IN_PROGRESS"] } },
      select: { title: true },
    });
    existingTitles = new Set(existing.map((e) => e.title.trim().toLowerCase()));
  } catch {
    // If we can't read existing rows, fall back to writing nothing rather than
    // risk flooding the board with duplicates.
    console.error("[nightly-scan] could not load existing improvements; aborting writes");
    await safeDisconnect();
    console.log(`[nightly-scan] wrote 0 proposals (batchId=${batchId})`);
    return;
  }

  // Also dedup within this run (two collectors could produce the same title).
  const seenThisRun = new Set<string>();
  let written = 0;

  for (const p of proposals) {
    const key = p.title.trim().toLowerCase();
    if (existingTitles.has(key) || seenThisRun.has(key)) continue;
    seenThisRun.add(key);
    try {
      await db.improvement.create({
        data: {
          batchId,
          category: p.category,
          severity: p.severity,
          title: p.title,
          summary: p.summary,
